import os, glob, re

def load_session_grids():
    """Load all demo pairs and test input from the current session log"""
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        print("No session dir found")
        return {}

    # Find the session log file
    try:
        session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
        with open(session_file, 'r') as f:
            content = f.read()
    except:
        print(f"Could not read session file: {session_file}")
        return {}

    G = {}
    # Find all demo pairs and test inputs
    pattern = re.compile(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n')
    matches = pattern.findall(content)

    for match in matches:
        kind, h, w = match
        k = kind
        start_pos = content.find(k)

        # Extract the grid
        lines = content[start_pos:start_pos + h * 25].strip().replace('\n', '\n').split('\n')
        grid = []
        for line in lines:
            if line.strip():
                grid.append([int(x) for x in line.split()])

        # Normalize size check
        if len(grid) == int(h):
            G[k] = grid

    print(f"Found {len(G)} grids:")
    for k, v in G.items():
        print(f"  {k}: {len(v)}x{len(v[0]) if v else 0}")
    return G

G = load_session_grids()

